INSERT OR REPLACE INTO LocalizedText (Language, Tag, Text) VALUES
    ('en_US', 'LOC_VICTORY_HEGEMONY_NAME', 'Hegemony Victory'),
    ('en_US', 'LOC_VICTORY_HEGEMONY_DESCRIPTION', 'Lead every living major rival in score. Exceed their combined Food, Production, Science, Culture, Faith, positive net Gold income, and military strength. Each civilization’s military strength is based on current units and their remaining health, rounded down after summing. Treasury Gold is excluded. Hold more than half the completed world wonders and more than half the city-states with a suzerain. Each majority is automatic when its world total is zero. Applies in Gathering Storm games without teams.'),
    ('en_US', 'LOC_VICTORY_HEGEMONY_BLURB', 'The winning civilization has united prosperity, knowledge, faith, and military might. Its wonders bear witness to an age of achievement, and city-states look to it for leadership. Its hegemony will shape the world for generations.'),
    ('zh_Hans_CN', 'LOC_VICTORY_HEGEMONY_NAME', '霸权胜利'),
    ('zh_Hans_CN', 'LOC_VICTORY_HEGEMONY_DESCRIPTION', '总分超过所有存活的主要文明对手。食物、生产力、科技、文化、信仰、净金币和军力分别超过对手合计。净金币仅计入对手的正净收入。军力按现有单位及其剩余生命值计算，各文明汇总后向下取整。国库金币不计入军力。拥有超过半数的已完工世界奇观，并担任超过半数有宗主城邦的宗主。后两项的全图计入数量为零时自动满足。适用于风云变幻规则集下的非组队对局。'),
    ('zh_Hans_CN', 'LOC_VICTORY_HEGEMONY_BLURB', '繁荣、知识、信仰和军力汇聚于这个获胜文明。宏伟的奇观见证它的盛世，众多城邦拥戴它为宗主。它的霸权将在未来数代塑造这个世界。');
